-- =====================================================================
-- Libraro: library permissions and Basic / Pro plans (15 Nov 2026) — for the live DB, phpMyAdmin.
-- Same result as the migrations 2026_11_15_000001 to _000006. Run AFTER
-- db/libraro_live_db_changes_2026-11-13.sql. Plain statements (no variables), MariaDB 10.3+.
-- Rows are found by name, never by id. Safe to run again. TAKE A FULL BACKUP FIRST.
-- =====================================================================
SET NAMES utf8mb4;

-- 0. a copy of everything this file changes (kept; drop it later when happy)
CREATE TABLE IF NOT EXISTS `bk20261115_permissions` AS SELECT * FROM `permissions` WHERE `guard_name` = 'library';
CREATE TABLE IF NOT EXISTS `bk20261115_subscription_permission` AS SELECT * FROM `subscription_permission`;
CREATE TABLE IF NOT EXISTS `bk20261115_library_user_permissions` AS SELECT * FROM `library_user_permissions`;
CREATE TABLE IF NOT EXISTS `bk20261115_permission_categories` AS SELECT * FROM `permission_categories`;
CREATE TABLE IF NOT EXISTS `bk20261115_subscription_plan_features` AS SELECT * FROM `subscription_plan_features`;
CREATE TABLE IF NOT EXISTS `bk20261115_libraries_plan` AS SELECT `id`, `library_type` FROM `libraries`;
CREATE TABLE IF NOT EXISTS `bk20261115_menus` AS SELECT `id`, `url`, `has_permissions` FROM `menus`;

-- 1. names without trailing spaces (MySQL '=' ignores them, so compare lengths)
UPDATE `permissions` SET `name` = TRIM(`name`), `updated_at` = NOW() WHERE `guard_name` = 'library' AND CHAR_LENGTH(`name`) <> CHAR_LENGTH(TRIM(`name`));

-- 2. categories: clear names, and the new one
UPDATE `permission_categories` SET `name` = 'Dashboard', `updated_at` = NOW() WHERE `name` = 'Dashboard Permission';
UPDATE `permission_categories` SET `name` = 'Menus', `updated_at` = NOW() WHERE `name` = 'Menu Permission';
UPDATE `permission_categories` SET `name` = 'Learner Operations', `updated_at` = NOW() WHERE `name` = 'Operation Permission';
UPDATE `permission_categories` SET `name` = 'Branch Settings', `updated_at` = NOW() WHERE `name` = 'Branch Operation Pemission';
UPDATE `permission_categories` SET `name` = 'Shifts', `updated_at` = NOW() WHERE `name` = 'Seat Plan Permission';
UPDATE `permission_categories` SET `name` = 'Reports', `updated_at` = NOW() WHERE `name` = 'Report Permission';
UPDATE `permission_categories` SET `name` = 'Advanced Features', `updated_at` = NOW() WHERE `name` = 'Advanced Permission';
UPDATE `permission_categories` SET `name` = 'Notifications', `updated_at` = NOW() WHERE `name` = 'Notification Permission';
UPDATE `permission_categories` SET `name` = 'Masters', `updated_at` = NOW() WHERE `name` = 'Master Permissions';

-- 3. permissions the panel checks that did not exist yet

-- 4. menus ask for the right permission
UPDATE `menus` SET `has_permissions` = 'Library Settings', `updated_at` = NOW() WHERE `has_permissions` = 'Library Genral Settings';
UPDATE `menus` SET `has_permissions` = 'Global Discount', `updated_at` = NOW() WHERE `guard` = 'library' AND `url` = 'global-discount.index';
UPDATE `menus` SET `has_permissions` = 'Student Quiz', `updated_at` = NOW() WHERE `guard` = 'library' AND `url` = 'quiz.index';
UPDATE `menus` SET `has_permissions` = 'Demo Inquiry', `updated_at` = NOW() WHERE `guard` = 'library' AND `url` = 'demo-users.index';

-- 5. remove the permissions nothing checks (copies are in bk20261115_*)
DELETE FROM `subscription_permission` WHERE `permission_id` IN (SELECT `id` FROM `permissions` WHERE `guard_name` = 'library' AND `name` IN ('Welcome Banner', 'Delate Seat Count', 'Total Seats', 'Library Register', 'Learners History', 'Future Bookings', 'Library Master Console', 'Library Corner', 'Library configuration', 'Student Corner', 'Show / Hide Options', 'Video Tutorial', 'Video Training', 'Suggestions', 'Feedback', 'Complaints', 'Book Category', 'Reminder Notification', 'Download Receipt', 'Library Activity Report', 'Activity Report', 'Attendence Report', 'Learner Login', 'Library filter', 'Extended Seat Highlighted', 'Expired Seat highlight', 'Pay Later Seat Highlight', 'Pending Payment Highlight', 'Overdue Payment Highlight', 'Email Notification'));
DELETE FROM `library_user_permissions` WHERE `permission_id` IN (SELECT `id` FROM `permissions` WHERE `guard_name` = 'library' AND `name` IN ('Welcome Banner', 'Delate Seat Count', 'Total Seats', 'Library Register', 'Learners History', 'Future Bookings', 'Library Master Console', 'Library Corner', 'Library configuration', 'Student Corner', 'Show / Hide Options', 'Video Tutorial', 'Video Training', 'Suggestions', 'Feedback', 'Complaints', 'Book Category', 'Reminder Notification', 'Download Receipt', 'Library Activity Report', 'Activity Report', 'Attendence Report', 'Learner Login', 'Library filter', 'Extended Seat Highlighted', 'Expired Seat highlight', 'Pay Later Seat Highlight', 'Pending Payment Highlight', 'Overdue Payment Highlight', 'Email Notification'));
DELETE FROM `role_has_permissions` WHERE `permission_id` IN (SELECT `id` FROM `permissions` WHERE `guard_name` = 'library' AND `name` IN ('Welcome Banner', 'Delate Seat Count', 'Total Seats', 'Library Register', 'Learners History', 'Future Bookings', 'Library Master Console', 'Library Corner', 'Library configuration', 'Student Corner', 'Show / Hide Options', 'Video Tutorial', 'Video Training', 'Suggestions', 'Feedback', 'Complaints', 'Book Category', 'Reminder Notification', 'Download Receipt', 'Library Activity Report', 'Activity Report', 'Attendence Report', 'Learner Login', 'Library filter', 'Extended Seat Highlighted', 'Expired Seat highlight', 'Pay Later Seat Highlight', 'Pending Payment Highlight', 'Overdue Payment Highlight', 'Email Notification'));
DELETE FROM `model_has_permissions` WHERE `permission_id` IN (SELECT `id` FROM `permissions` WHERE `guard_name` = 'library' AND `name` IN ('Welcome Banner', 'Delate Seat Count', 'Total Seats', 'Library Register', 'Learners History', 'Future Bookings', 'Library Master Console', 'Library Corner', 'Library configuration', 'Student Corner', 'Show / Hide Options', 'Video Tutorial', 'Video Training', 'Suggestions', 'Feedback', 'Complaints', 'Book Category', 'Reminder Notification', 'Download Receipt', 'Library Activity Report', 'Activity Report', 'Attendence Report', 'Learner Login', 'Library filter', 'Extended Seat Highlighted', 'Expired Seat highlight', 'Pay Later Seat Highlight', 'Pending Payment Highlight', 'Overdue Payment Highlight', 'Email Notification'));
DELETE FROM `permissions` WHERE `guard_name` = 'library' AND `name` IN ('Welcome Banner', 'Delate Seat Count', 'Total Seats', 'Library Register', 'Learners History', 'Future Bookings', 'Library Master Console', 'Library Corner', 'Library configuration', 'Student Corner', 'Show / Hide Options', 'Video Tutorial', 'Video Training', 'Suggestions', 'Feedback', 'Complaints', 'Book Category', 'Reminder Notification', 'Download Receipt', 'Library Activity Report', 'Activity Report', 'Attendence Report', 'Learner Login', 'Library filter', 'Extended Seat Highlighted', 'Expired Seat highlight', 'Pay Later Seat Highlight', 'Pending Payment Highlight', 'Overdue Payment Highlight', 'Email Notification');

-- 6. every permission in the right category
UPDATE `permissions` p JOIN (SELECT 'QR Seat Booking' AS `n`, 'Learner Operations' AS `c` UNION ALL SELECT 'Download Payment Receipt' AS `n`, 'Payments & Expenses' AS `c` UNION ALL SELECT 'Receipt Generation' AS `n`, 'Payments & Expenses' AS `c` UNION ALL SELECT 'Pending Payment' AS `n`, 'Payments & Expenses' AS `c` UNION ALL SELECT 'Add Misllaneous Payment' AS `n`, 'Payments & Expenses' AS `c` UNION ALL SELECT 'Add Daily Expense' AS `n`, 'Payments & Expenses' AS `c` UNION ALL SELECT 'Monthly Report' AS `n`, 'Reports' AS `c` UNION ALL SELECT 'Import Learners' AS `n`, 'Advanced Features' AS `c` UNION ALL SELECT 'Import Library Settings' AS `n`, 'Advanced Features' AS `c` UNION ALL SELECT 'Manage Feature Toggles' AS `n`, 'Advanced Features' AS `c` UNION ALL SELECT 'User management' AS `n`, 'Advanced Features' AS `c` UNION ALL SELECT 'Add User' AS `n`, 'Advanced Features' AS `c` UNION ALL SELECT 'Add User Master' AS `n`, 'Masters' AS `c`) v ON v.`n` = p.`name` JOIN `permission_categories` pc ON pc.`name` = v.`c` SET p.`permission_category_id` = pc.`id`, p.`updated_at` = NOW() WHERE p.`guard_name` = 'library';

-- 7. two plans: Smart's libraries move to Pro, Smart is removed; Basic keeps one branch
UPDATE `libraries` SET `library_type` = 3, `updated_at` = NOW() WHERE `library_type` = 2;
UPDATE `subscriptions` SET `deleted_at` = NOW(), `updated_at` = NOW() WHERE `id` = 2 AND `deleted_at` IS NULL;
UPDATE `subscriptions` SET `max_branches` = 1, `updated_at` = NOW() WHERE `id` = 1;

-- 8. plan permissions: Pro = every library permission, Basic = all but the Pro-only ones
DELETE FROM `subscription_permission` WHERE `subscription_id` IN (1, 2, 3);

-- 9. staff keep what they could do before (these options had no permission until now)

-- 10. plan feature list (pricing, choose plan): old rows soft-deleted, the Basic / Pro list added (once)
UPDATE `subscription_plan_features` SET `deleted_at` = NOW() WHERE `deleted_at` IS NULL AND (SELECT `id` FROM (SELECT `id` FROM `subscription_plan_features` WHERE `deleted_at` IS NULL AND `name` = 'Renew and swap seat' LIMIT 1) mk) IS NULL;

-- 11. mark the four migrations as run

-- 12. extra payment: advance or a higher price (migration 2026_11_15_000005_extra_payment_as_advance_or_price; docs/LEARNER_ADVANCE.md)
ALTER TABLE `branches` ADD COLUMN IF NOT EXISTS `allow_higher_price` tinyint(1) NOT NULL DEFAULT 0 AFTER `fixed_billing_date`;

-- 13. advance received per bill (migration 2026_11_15_000006_learner_transactions_advance_received; docs/LEARNER_ADVANCE.md)
ALTER TABLE `learner_transactions` ADD COLUMN IF NOT EXISTS `advance_received` decimal(10,2) NOT NULL DEFAULT 0.00 AFTER `refund`;
UPDATE `learner_transactions` t SET t.`advance_received` = t.`refund` WHERE t.`refund` > 0 AND t.`advance_received` = 0 AND t.`deleted_at` IS NULL AND NOT EXISTS (SELECT 1 FROM `learner_transaction_activity` a WHERE a.`learner_transaction_id` = t.`id` AND a.`payment_type` IN ('CHANGE PLAN', 'EDIT'));

-- Done. Spatie permission cache: `php artisan permission:cache-reset` if you have a shell (else it refreshes by itself).
