INSERT INTO `library_user_permissions` (`library_user_id`, `permission_id`, `created_at`) SELECT s.`uid`, p.`id`, NOW() FROM (SELECT DISTINCT lup.`library_user_id` AS `uid` FROM `library_user_permissions` lup JOIN `permissions` pb ON pb.`id` = lup.`permission_id` AND pb.`guard_name` = 'library' AND pb.`name` = 'Edit Seat') s JOIN `permissions` p ON p.`guard_name` = 'library' AND p.`name` = 'Edit Plan' WHERE NOT EXISTS (SELECT 1 FROM `library_user_permissions` x WHERE x.`library_user_id` = s.`uid` AND x.`permission_id` = p.`id`);
INSERT INTO `library_user_permissions` (`library_user_id`, `permission_id`, `created_at`) SELECT s.`uid`, p.`id`, NOW() FROM (SELECT lu.`id` AS `uid` FROM `library_users` lu WHERE lu.`deleted_at` IS NULL) s JOIN `permissions` p ON p.`guard_name` = 'library' AND p.`name` = 'Learner Activity' WHERE NOT EXISTS (SELECT 1 FROM `library_user_permissions` x WHERE x.`library_user_id` = s.`uid` AND x.`permission_id` = p.`id`);
INSERT INTO `library_user_permissions` (`library_user_id`, `permission_id`, `created_at`) SELECT s.`uid`, p.`id`, NOW() FROM (SELECT lu.`id` AS `uid` FROM `library_users` lu WHERE lu.`deleted_at` IS NULL) s JOIN `permissions` p ON p.`guard_name` = 'library' AND p.`name` = 'Learner Transactions' WHERE NOT EXISTS (SELECT 1 FROM `library_user_permissions` x WHERE x.`library_user_id` = s.`uid` AND x.`permission_id` = p.`id`);
